<script>
 import { onMount } from 'svelte'; let items = $state([]); let index = $state(0); let open = $state(false);
 onMount(() => { fetch('/api/announcements').then(r=>r.json()).then(x=>{items=x.items||[];open=items.length>0}).catch(()=>{}); });
 function mark(){const x=items[index]; if(!x)return; void fetch('/api/announcements',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({announcement:x.id,revision:x.revision})}); index++; if(index>=items.length)open=false;}
</script>
{#if open && items[index]}<div class="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4" role="presentation" onclick={(event)=>event.target===event.currentTarget&&mark()}><aside class="w-[min(32rem,calc(100vw-2rem))] rounded-2xl border bg-white p-6 text-slate-900 shadow-2xl" role="dialog" aria-modal="true"><div class="flex justify-between"><strong>ประกาศ</strong><button onclick={mark} aria-label="ปิด">×</button></div><h2 class="mt-2 text-lg font-semibold">{items[index].title}</h2><p class="mt-2 whitespace-pre-wrap text-sm">{items[index].body}</p>{#if items[index].link_url}<a class="mt-3 inline-block underline" href={items[index].link_url} target="_blank" rel="noreferrer">{items[index].link_label||'อ่านเพิ่มเติม'}</a>{/if}<button class="mt-4 w-full rounded-lg bg-slate-900 px-3 py-2 text-white" onclick={mark}>รับทราบ</button></aside></div>{/if}
